   151	            return Long.parseLong(id);
   152	        } catch (NumberFormatException notANumber) {
   153	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
   154	        }
   155	    }
